VID.narration = {"look":{"bar":false},"scenes":[{"dur":9.288,"caps":[[0.5,8.43,"Lecture twelve. Particle swarm optimisation. This is how a swarm of simple guesses finds the best spot."]],"warp":[[0,0],[0.5,0.9],[9.288,4]]},{"dur":30,"caps":[[0.5,4.43,"Each dot is a particle: one guess at the answer."],[4.68,11.57,"Its guess is a position: two numbers on the map."],[11.82,16.15,"The odour where it stands is its fitness."],[16.4,22.65,"Each particle also has a velocity: its next move."],[22.9,28.67,"No particle sees the map, only the odour underfoot."]],"warp":[[0,0],[0.5,0.5],[4.68,2.8],[11.82,5.2],[16.4,7.4],[22.9,9.4],[30,12]]},{"dur":23.452,"caps":[[0.55,4.24,"To move, a particle adds its velocity to its position."],[4.49,11.3,"(3, 5) plus (2, −1) lands on (5, 4)."],[11.55,17.48,"With no pulls, every dot just flies straight on."],[17.73,22.38,"Nothing steers them towards the scent."]],"warp":[[0,0],[0.55,1],[4.49,3.2],[11.55,6.2],[17.73,9.2],[23.452,13]]},{"dur":31.719,"caps":[[0.5,3.63,"Follow one particle for one step."],[3.88,7.57,"Grey: the velocity it already has."],[7.82,13.35,"Purple: a pull towards its own best spot, p."],[13.6,19.13,"Orange: a pull towards the swarm's best spot, g."],[19.38,24.51,"Added head to tail, they make the new velocity."],[24.76,31.09,"Its new odour, 25, does not beat 52, so p stays."]],"warp":[[0,0],[0.5,0.5],[3.88,2.6],[7.82,4.5],[13.6,6.3],[19.38,8.3],[24.76,11.6],[31.719,16]]},{"dur":39.822,"caps":[[0.55,8.48,"One dimension: x is 4, its best 7, the swarm's 2."],[8.73,16.82,"c₁, c₂ set how hard; z₁, z₂ are random draws."],[17.07,19.96,"It keeps its velocity of 1."],[20.21,26.14,"The pull to its own best adds 3."],[26.39,33.04,"The pull to the swarm's best adds minus 2."],[33.29,38.66,"New velocity 2, so it moves from 4 to 6."]],"warp":[[0,0],[0.55,1],[8.73,3.1],[17.07,5.2],[20.21,6.8],[26.39,8.6],[33.29,10.4],[39.822,13]]},{"dur":16.672,"caps":[[0.5,4.51,"z₁ and z₂ are fresh random numbers every step."],[4.76,8.37,"Roll again and the same particle lands elsewhere."],[8.62,12.07,"Each hollow dot is one possible landing spot."],[12.32,15.77,"This spread stops the swarm settling too soon."]],"warp":[[0,0],[0.5,0.9],[4.76,2.8],[8.62,5.2],[12.32,8.8],[16.672,11]]},{"dur":23.359,"caps":[[0.77,4.38,"All 14 particles take that step together."],[4.63,10.96,"The swarm's best climbed: 66, 78, 85, then 99."],[11.21,14.82,"Pulled to their own bests and the swarm's, they gather."],[15.07,17.64,"They swarm around the food and keep searching."],[17.89,22.06,"Nobody saw the map, yet the swarm found the food."]],"warp":[[0,0],[0.77,1.4],[4.63,5],[11.21,7.6],[15.07,10.2],[17.89,12.1],[23.359,15]]},{"dur":26.75,"caps":[[0.5,8.27,"Here each particle keeps 60% of its old velocity."],[8.52,13.33,"Step 7: odour 97, a good enough answer."],[13.58,17.75,"Step 19: the swarm has shrunk to almost a point."],[18,22.73,"Then 8 steps with no new best, then the step limit."],[22.98,26.11,"Any one of the four rules can end the run."]],"warp":[[0,0],[0.5,0.8],[8.52,2.6],[13.58,4.8],[18,10.3],[22.98,12.1],[26.75,14]]},{"dur":35.131,"caps":[[0.55,5.92,"A bit is 0 or 1: adding 0.7 makes no sense."],[6.17,10.5,"Binary PSO keeps v between 0 and 1."],[10.75,18.04,"The two pulls add 0.2 and 0.1: v is now 0.8."],[18.29,24.7,"Draw rand(): 0.55 is below 0.8, so the bit is 1."],[24.95,29.44,"So v is the chance of a 1, drawn every step."],[29.69,33.22,"Here 16 of 20 draws come out as 1."]],"warp":[[0,0],[0.55,1],[6.17,4.2],[10.75,5.8],[18.29,7.8],[24.95,10.4],[29.69,12.9],[35.131,15]]},{"dur":13.538,"caps":[],"warp":[[0,0],[0.5,0.9],[3.96,2],[9.66,3.1],[13.538,9]]}]};
